package com.bank.payments.application;

import com.bank.payments.adapters.in.rest.PayOrderRequest;
import com.bank.payments.adapters.in.rest.PayOrderResponse;
import com.bank.payments.domain.error.BusinessError;
import com.bank.payments.domain.model.Account;
import com.bank.payments.domain.model.PaymentOrder;
import com.bank.payments.domain.port.AccountRepository;
import com.bank.payments.domain.port.MovementGateway;
import com.bank.payments.domain.port.OrderRepository;
import java.math.BigDecimal;
import java.util.Optional;

/**
 * Application service of PayOrder (legacy PAGOORD, with the rules of PAGODEB folded in).
 *
 * UNRESOLVED_DEPENDENCY: the copybooks ORDREG / CTAREG are not available, so the stored values
 * of ORD-PENDIENTE and CTA-ACTIVA are not evidenced by the source. 'P' and 'A' are the values
 * used by the tests for pending / active; any other value is "not pending" / "not active".
 */
public class PayOrderService {

    private static final String LEGACY_CODE = "-1";

    private static final String ORDER_PENDING = "P";
    private static final String ACCOUNT_ACTIVE = "A";

    private static final BigDecimal LARGE_ORDER_LIMIT = new BigDecimal("50000");
    private static final BigDecimal COMMISSION_ZERO = new BigDecimal("0.00");
    private static final BigDecimal COMMISSION_WEB = new BigDecimal("1.00");
    private static final BigDecimal COMMISSION_OTHER = new BigDecimal("2.50");

    private final OrderRepository orders;
    private final AccountRepository accounts;
    private final MovementGateway movements;

    public PayOrderService(OrderRepository orders, AccountRepository accounts, MovementGateway movements) {
        this.orders = orders;
        this.accounts = accounts;
        this.movements = movements;
    }

    public PayOrderResponse execute(PayOrderRequest request) {
        // 2100-VALIDAR-ENTRADA (nested IFs: first failing check wins)
        String orderText = fixed(request.orderNumber(), 7);
        if (!isNumeric(orderText) || isAllZeros(orderText)) {
            throw error("INVALID_ORDER_NUMBER", "NUMERO DE ORDEN INVALIDO");
        }
        String accountType = request.accountType();
        if (!"CTE".equals(accountType) && !"AHO".equals(accountType) && !"VIR".equals(accountType)) {
            throw error("ACCOUNT_TYPE_NOT_ALLOWED", "TIPO DE CUENTA NO PERMITIDO");
        }
        String channel = request.channel();
        if (!"WEB".equals(channel) && !"OFI".equals(channel)) {
            throw error("CHANNEL_NOT_ALLOWED", "CANAL NO PERMITIDO");
        }
        if ("OFI".equals(channel) && isSpaces(request.approvalKey())) {
            throw error("APPROVAL_KEY_REQUIRED", "CLAVE DE APROBACION REQUERIDA");
        }

        // 2200-LEER-ORDEN
        Integer orderKey = Integer.valueOf(Integer.parseInt(orderText));
        Optional<PaymentOrder> found = orders.findByKey(orderKey, request.companyId());
        if (found.isEmpty()) {
            throw error("ORDER_NOT_FOUND", "ORDEN NO EXISTE");
        }
        PaymentOrder order = found.get();
        if (!ORDER_PENDING.equals(order.status())) {
            throw error("ORDER_NOT_PENDING", "ORDEN NO ESTA PENDIENTE");
        }
        if (request.amount().compareTo(order.value()) != 0) {
            throw error("AMOUNT_MISMATCH", "VALOR NO COINCIDE CON LA ORDEN");
        }

        // 2300-CALCULAR-COMISION
        BigDecimal commission;
        if (order.value().compareTo(LARGE_ORDER_LIMIT) >= 0) {
            commission = COMMISSION_ZERO;
        } else if ("WEB".equals(channel)) {
            commission = COMMISSION_WEB;
        } else {
            commission = COMMISSION_OTHER;
        }
        BigDecimal total = order.value().add(commission);

        // 2400-DEBITAR-CUENTA (rules of PAGODEB, in the same order)
        Optional<Account> foundAccount = accounts.findByNumber(request.accountNumber());
        if (foundAccount.isEmpty()) {
            // DEB-RESP '30' -> CUENTA NO VALIDA
            throw error("INVALID_ACCOUNT", "CUENTA NO VALIDA");
        }
        Account account = foundAccount.get();
        if (!equalsFixed(account.accountType(), accountType)) {
            // DEB-RESP '40' -> CUENTA NO VALIDA
            throw error("INVALID_ACCOUNT", "CUENTA NO VALIDA");
        }
        if (!ACCOUNT_ACTIVE.equals(account.status())) {
            // DEB-RESP '10'
            throw error("ACCOUNT_INACTIVE", "CUENTA INACTIVA");
        }
        if (account.balance().compareTo(total) < 0) {
            // DEB-RESP '20'
            throw error("INSUFFICIENT_FUNDS", "SALDO INSUFICIENTE");
        }
        accounts.updateBalance(request.accountNumber(), account.balance().subtract(total));

        // 2500-REGISTRAR-PAGO
        long movementNumber = movements.registerMovement(order.orderNumber());
        orders.markPaid(order.orderNumber(), request.companyId(), Long.valueOf(movementNumber), commission);

        // 2600-ENVIAR-RESULTADO
        return new PayOrderResponse(order.orderNumber(), commission, Long.valueOf(movementNumber),
                "PAGO REALIZADO");
    }

    private static BusinessError error(String code, String message) {
        return new BusinessError(code, LEGACY_CODE, message);
    }

    /** Emulates a PIC X(n) field: right-padded with spaces / truncated to n; null is treated as spaces. */
    private static String fixed(String value, int length) {
        String v = value == null ? "" : value;
        if (v.length() > length) {
            return v.substring(0, length);
        }
        StringBuilder sb = new StringBuilder(v);
        while (sb.length() < length) {
            sb.append(' ');
        }
        return sb.toString();
    }

    private static boolean isNumeric(String s) {
        if (s.isEmpty()) {
            return false;
        }
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c < '0' || c > '9') {
                return false;
            }
        }
        return true;
    }

    private static boolean isAllZeros(String s) {
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) != '0') {
                return false;
            }
        }
        return true;
    }

    private static boolean isSpaces(String s) {
        if (s == null) {
            return true;
        }
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) != ' ') {
                return false;
            }
        }
        return true;
    }

    /** COBOL alphanumeric comparison: the shorter operand is padded with spaces. */
    private static boolean equalsFixed(String a, String b) {
        String x = a == null ? "" : a;
        String y = b == null ? "" : b;
        int len = Math.max(x.length(), y.length());
        return fixed(x, len).equals(fixed(y, len));
    }
}

